const ns=(host,path)=>'http:'+String.fromCharCode(47,47)+host+'/'+path;
const xmlEsc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
function colName(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function sheetXml(rows){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="${ns('schemas.openxmlformats.org','spreadsheetml/2006/main')}"><sheetData>${rows.map((r,y)=>`<row r="${y+1}">${r.map((v,x)=>`<c r="${colName(x)}${y+1}" t="inlineStr"><is><t>${xmlEsc(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`}
function crc32(bytes){let c=-1;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^-1)>>>0}
function zipStore(files){const enc=new TextEncoder(),parts=[],centrals=[];let offset=0;for(const [name,content] of Object.entries(files)){const nb=enc.encode(name),data=enc.encode(content),crc=crc32(data),local=new Uint8Array(30+nb.length+data.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0,true);v.setUint16(8,0,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,nb.length,true);local.set(nb,30);local.set(data,30+nb.length);parts.push(local);const cd=new Uint8Array(46+nb.length),d=new DataView(cd.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0,true);d.setUint16(10,0,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,nb.length,true);d.setUint32(42,offset,true);cd.set(nb,46);centrals.push(cd);offset+=local.length}const centralSize=centrals.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,centrals.length,true);v.setUint16(10,centrals.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...parts,...centrals,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function workbook(sheets){const names=Object.keys(sheets);const files={'[Content_Types].xml':`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="${ns('schemas.openxmlformats.org','package/2006/content-types')}"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,'_rels/.rels':`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="${ns('schemas.openxmlformats.org','package/2006/relationships')}"><Relationship Id="rId1" Type="${ns('schemas.openxmlformats.org','officeDocument/2006/relationships/officeDocument')}" Target="xl/workbook.xml"/></Relationships>`,'xl/workbook.xml':`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="${ns('schemas.openxmlformats.org','spreadsheetml/2006/main')}" xmlns:r="${ns('schemas.openxmlformats.org','officeDocument/2006/relationships')}"><sheets>${names.map((n,i)=>`<sheet name="${xmlEsc(n)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="${ns('schemas.openxmlformats.org','package/2006/relationships')}">${names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${ns('schemas.openxmlformats.org','officeDocument/2006/relationships/worksheet')}" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`};names.forEach((n,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=sheetXml(sheets[n]));return zipStore(files)}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function readWorkbook(file){const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer),files={};let offset=0;while(offset+30<bytes.length&&view.getUint32(offset,true)===0x04034b50){const method=view.getUint16(offset+8,true),size=view.getUint32(offset+18,true),nameLen=view.getUint16(offset+26,true),extra=view.getUint16(offset+28,true),name=new TextDecoder().decode(bytes.slice(offset+30,offset+30+nameLen)),start=offset+30+nameLen+extra,body=bytes.slice(start,start+size);files[name]=method===0?body:method===8?new Uint8Array(await new Response(new Blob([body]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer()):null;if(!files[name])throw Error('Ukjent komprimeringsmetode');offset=start+size}const dec=new TextDecoder(),parse=path=>new DOMParser().parseFromString(dec.decode(files[path]),'application/xml'),all=(doc,name)=>Array.from(doc.getElementsByTagNameNS('*',name));let sheetPath=Object.keys(files).find(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x));if(files['xl/workbook.xml']&&files['xl/_rels/workbook.xml.rels']){const book=parse('xl/workbook.xml'),rels=parse('xl/_rels/workbook.xml.rels'),sheetNodes=all(book,'sheet'),relNodes=all(rels,'Relationship'),targets=Object.fromEntries(relNodes.map(x=>[x.getAttribute('Id'),x.getAttribute('Target')])),chosen=sheetNodes.find(x=>x.getAttribute('name')==='DATA')||sheetNodes[0];if(chosen){const rid=chosen.getAttributeNS(ns('schemas.openxmlformats.org','officeDocument/2006/relationships'),'id')||chosen.getAttribute('r:id'),target=targets[rid];if(target){const resolved=target.startsWith('/')?target.slice(1):target.startsWith('xl/')?target:`xl/${target.replace(/^\.\//,'')}`;if(files[resolved])sheetPath=resolved}}}if(!sheetPath)throw Error('Fant ikke DATA-arket i XLSX-filen');const shared=files['xl/sharedStrings.xml']?all(parse('xl/sharedStrings.xml'),'si').map(e=>all(e,'t').map(t=>t.textContent).join('')):[],doc=parse(sheetPath);return all(doc,'row').map(row=>{const vals=[];all(row,'c').forEach(cell=>{const ref=cell.getAttribute('r'),letters=ref.match(/[A-Z]+/)[0];let idx=0;for(const c of letters)idx=idx*26+c.charCodeAt(0)-64;idx--;const raw=all(cell,'v')[0]?.textContent||all(cell,'t')[0]?.textContent||'';vals[idx]=cell.getAttribute('t')==='s'?shared[Number(raw)]||'':raw});return vals.map(x=>x||'')})}
function rowsForExport(){return [xlsxColumns,...[...db.items].sort((a,b)=>a.name.localeCompare(b.name,'no')).map((i,n)=>[i.internalId||`DEMO-HUL-${String(n+1).padStart(3,'0')}`,i.demoUpdateKey||`DEMO-UPDATE-${String(n+1).padStart(3,'0')}`,i.name,i.category,i.location,i.event,i.status,i.quantity,i.condition,i.responsible,i.value,i.notes]) ]}
function importExport(){adminShell('import-export','Import / Eksport',`<section class="panel"><h2>Eksporter lagervarer</h2><p>Eksporterer varer til en lokal XLSX-fil med DATA, FORKLARING og GYLDIGE_VERDIER. Oppdateringsnøkkel er kun en syntetisk demo-ID.</p><button class="button primary" id="exportXlsx">Eksporter XLSX</button></section><section class="panel"><h2>Last ned importmal</h2><p>Malfil med kolonneforklaringer og gyldige status-/tilstandsverdier.</p><button class="button" id="templateXlsx">Last ned importmal</button></section><section class="panel"><h2>Importer lagervarer fra XLSX</h2><p>Velg en XLSX-fil; innholdet leses kun lokalt. Først vises valideringsfeil og forhåndsvisning. Ingenting endres før bekreftelse.</p><label class="field">XLSX-fil<input id="xlsxFile" type="file" accept=".xlsx" required></label><div id="importPreview"></div></section>`);bind('exportXlsx','click',()=>downloadBlob(workbook({DATA:rowsForExport(),FORKLARING:xlsxDescriptions,GYLDIGE_VERDIER:[['Felt','Gyldige verdier'],['status','tilgjengelig, utlant, vedlikehold, arkivert'],['tilstand','god, ok, slitt, defekt']]}),`lager-demo-${new Date().toISOString().slice(0,10)}.xlsx`));bind('templateXlsx','click',()=>downloadBlob(workbook({DATA:[xlsxColumns],FORKLARING:xlsxDescriptions,GYLDIGE_VERDIER:[['Felt','Gyldige verdier'],['status','tilgjengelig, utlant, vedlikehold, arkivert'],['tilstand','god, ok, slitt, defekt']]}),'lager-importmal-demo.xlsx'));bind('xlsxFile','change',async e=>{const target=document.querySelector('#importPreview');try{const rows=await readWorkbook(e.target.files[0]),head=rows[0].map(x=>String(x).trim().toLowerCase()),idx=Object.fromEntries(head.map((x,n)=>[x,n]));if(!('navn'in idx))throw Error('Kolonnen "navn" mangler i DATA-arket.');const preview=rows.slice(1).map((r,n)=>({row:n+2,values:Object.fromEntries(xlsxColumns.map(k=>[k,String(r[idx[k]]||'').trim()]))})).filter(x=>Object.values(x.values).some(Boolean));const errors=[];for(const x of preview){const v=x.values;if(!v.navn)errors.push(`Rad ${x.row}: Navn er påkrevd.`);if(v.status&&!['tilgjengelig','utlant','vedlikehold','arkivert'].includes(v.status))errors.push(`Rad ${x.row}: Ugyldig status ${v.status}.`);if(v.tilstand&&!['god','ok','slitt','defekt'].includes(v.tilstand))errors.push(`Rad ${x.row}: Ugyldig tilstand ${v.tilstand}.`);if(v.antall&&(isNaN(Number(v.antall))||Number(v.antall)<0||!Number.isInteger(Number(v.antall))))errors.push(`Rad ${x.row}: Ugyldig antall.`);if(v.verdi&&isNaN(Number(v.verdi)))errors.push(`Rad ${x.row}: Ugyldig verdi.`)}window.pendingImport={preview,errors};target.innerHTML=`${errors.length?`<h3>Feil i import</h3><ul>${errors.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:'<h3>Forhåndsvisning — klar for import</h3>'}<div class="table-wrap"><table class="data-table"><thead><tr>${xlsxColumns.filter(k=>k!=='update_key').map(k=>`<th>${h(k)}</th>`).join('')}</tr></thead><tbody>${preview.map(x=>`<tr>${xlsxColumns.filter(k=>k!=='update_key').map(k=>`<td>${h(x.values[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="row-actions"><button id="confirmImport" class="button primary" ${errors.length?'disabled':''}>Bekreft import</button><button id="cancelImport" class="button">Avbryt</button></div>`;bind('cancelImport','click',()=>{window.pendingImport=null;target.innerHTML=''});bind('confirmImport','click',()=>{for(const {values:v} of window.pendingImport.preview){let i=v.update_key?db.items.find(x=>x.demoUpdateKey&&x.demoUpdateKey===v.update_key):null;if(!i){i={id:uid('vare'),status:'tilgjengelig',condition:'god',quantity:0,value:0,history:[],subItems:[],media:[],attributes:{},global:{},test:true};db.items.push(i)}const mapped={name:'navn',category:'kategori',location:'plassering',event:'lop',status:'status',condition:'tilstand',responsible:'ansvarlig',notes:'notat'};for(const [field,key] of Object.entries(mapped))if(v[key]!==''||!i.demoUpdateKey)i[field]=v[key]||i[field]||'';if(v.antall!==''||!i.demoUpdateKey)i.quantity=v.antall===''?0:Number(v.antall);if(v.verdi!==''||!i.demoUpdateKey)i.value=v.verdi===''?0:Number(v.verdi);if(v.update_key)i.demoUpdateKey=v.update_key;if(v.intern_id)i.internalId=v.intern_id;for(const k of ['category','location','event'])if(v[k])for(const term of v[k].split(',').map(x=>x.trim()).filter(Boolean))if(!db.terms[k].includes(term))db.terms[k].push(term)}window.pendingImport=null;target.innerHTML='';toast('XLSX-import fullført lokalt')})}catch(err){target.innerHTML=`<p role="alert">Importfeil: ${h(err.message)}. Kontroller at filen er en gyldig XLSX.</p>`}})}
function goAdmin(page){if(currentRole==='visitor'){app.innerHTML='<section class="panel"><h1>Administrasjon er ikke valgt</h1><p>Velg Lageransvarlig (simulert) eller Administrator (simulert) for å utforske kildeappens adminflater. Dette er bare UI-simulering, ikke innlogging eller tilgangskontroll.</p><a class="button" href="#/">Til offentlig portal</a></section>';return}if(page==='dashboard')dashboard();else if(page==='inventory'){const r=route();if(r.id)itemEditor(r.id);else inventory()}else if(page==='taxonomies')taxonomies();else if(page==='loans')loans();else if(page==='borrowers')borrowers();else if(page==='lists')lists();else if(page==='packages')packages();else if(page==='settings')settings();else if(page==='import-export')importExport();else if(page==='testdata')testdata();else dashboard()}
function render(){const r=route();adminNav.hidden=currentRole==='visitor';if(r.type==='admin')goAdmin(r.page);else if(r.type==='item')detail(decodeURIComponent(r.id||''));else if(r.type==='list')sharedList(decodeURIComponent(r.id||''));else portal();app.focus({preventScroll:true})}
role.addEventListener('change',()=>{currentRole=role.value;document.body.dataset.role=currentRole;if(currentRole!=='visitor'&&route().type!=='admin')location.hash='#/admin/dashboard';else render();toast(currentRole==='visitor'?'Besøkende-visning':'Simulert rolle valgt')});window.addEventListener('hashchange',render);document.body.dataset.role=currentRole;render();
function taxonomies(){const defs=[['category','Kategorier','category'],['location','Plasseringer','location'],['event','Løp/arrangement','event']];adminShell('taxonomies','Taksonomier',`<p>Kildens CPT bruker tre taksonomier: kategori, plassering og løp/arrangement.</p><div class="admin-columns">${defs.map(([key,title,field])=>{const values=db.terms[field];return `<section class="panel"><h2>${title}</h2><form data-term-form="${field}" class="row-actions"><label class="field">Ny term<input name="name" required></label>${field==='event'?'':`<label class="field">Overordnet ${title.toLowerCase()}<select name="parent"><option value="">Ingen · toppnivå</option>${values.map(v=>`<option value="${h(v)}">${h(v)}</option>`).join('')}</select></label>`}<button class="button primary">Legg til</button></form><ul>${values.map(v=>`<li>${db.termParents[field][v]?`↳ ${h(db.termParents[field][v])} / `:''}${h(v)} · ${db.items.filter(i=>(i[field]||'').split(',').map(x=>x.trim()).includes(v)).length} varer <button class="button" data-rename-term="${field}" data-old="${h(v)}">Gi nytt navn</button> <button class="button" data-delete-term="${field}" data-old="${h(v)}">Slett</button></li>`).join('')}</ul></section>`}).join('')}</div>`);document.querySelectorAll('[data-term-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),v=fd.get('name').trim(),field=form.dataset.termForm;if(db.terms[field].includes(v))return toast('Term finnes allerede');db.terms[field].push(v);if(field!=='event'&&fd.get('parent'))db.termParents[field][v]=fd.get('parent');toast(`Term «${v}» opprettet lokalt`);taxonomies()});document.querySelectorAll('[data-rename-term]').forEach(b=>b.onclick=()=>{askText('Gi term nytt navn',b.dataset.old,next=>{if(!next||db.terms[b.dataset.renameTerm].includes(next))return;db.items.forEach(i=>i[b.dataset.renameTerm]=(i[b.dataset.renameTerm]||'').split(',').map(x=>x.trim()===b.dataset.old?next:x.trim()).filter(Boolean).join(', '));db.terms[b.dataset.renameTerm]=db.terms[b.dataset.renameTerm].map(x=>x===b.dataset.old?next:x);const parents=db.termParents[b.dataset.renameTerm];if(parents[b.dataset.old]){parents[next]=parents[b.dataset.old];delete parents[b.dataset.old]}for(const key of Object.keys(parents))if(parents[key]===b.dataset.old)parents[key]=next;taxonomies()})});document.querySelectorAll('[data-delete-term]').forEach(b=>b.onclick=()=>{askConfirm('Slette termen fra alle varer?',()=>{db.items.forEach(i=>i[b.dataset.deleteTerm]=(i[b.dataset.deleteTerm]||'').split(',').map(x=>x.trim()).filter(x=>x!==b.dataset.old).join(', '));db.terms[b.dataset.deleteTerm]=db.terms[b.dataset.deleteTerm].filter(x=>x!==b.dataset.old);const parents=db.termParents[b.dataset.deleteTerm];delete parents[b.dataset.old];for(const key of Object.keys(parents))if(parents[key]===b.dataset.old)delete parents[key];taxonomies()})})}
